var s=document.createElement('style');s.id='pk-podglad';s.textContent="/* ===== Zmiana 1: sekcja \u201ePorozmawiajmy!\u201d + mapa lokalizacji (be\u017cowy pas nad stopk\u0105, na ka\u017cdej stronie) ===== */\n\n/* sekcja: r\u00f3wne odst\u0119py g\u00f3ra/d\u00f3\u0142 */\n.site-above-footer-wrap[data-section=\"section-above-footer-builder\"] {\n  padding: 96px 0 !important;\n}\n\n/* kontener: max 1200 px tre\u015bci, 2 kolumny 380 px + reszta */\n.site-above-footer-wrap[data-section=\"section-above-footer-builder\"] .ast-builder-grid-row {\n  grid-template-columns: 380px 1fr !important;\n  column-gap: 64px !important;\n  max-width: 1264px !important;\n  margin: 0 auto !important;\n  padding-left: 32px !important;\n  padding-right: 32px !important;\n  align-items: stretch !important;\n}\n\n/* lewa kolumna wype\u0142nia ca\u0142\u0105 wysoko\u015b\u0107 (potrzebne do wy\u015brodkowania ucha) */\n.site-footer-above-section-1,\n.site-footer-above-section-1 .footer-widget-area,\n.site-footer-above-section-1 .widget,\n.site-footer-above-section-1 .custom-html-widget {\n  height: 100%;\n  margin: 0 !important;\n}\n.site-footer-above-section-2 .widget,\n.site-footer-above-section-2 .footer-widget-area { margin: 0 !important; width: 100%; }\n\n/* nag\u0142\u00f3wki */\n.pk-h2 {\n  font-family: \"Instrument Serif\", serif !important;\n  font-weight: 400 !important;\n  font-size: 62px !important;\n  line-height: 1.05 !important;\n  color: #191919 !important;\n  margin: 0 !important;\n}\n.pk-h2--mapa { font-size: 52px !important; margin-bottom: 10px !important; }\n\n/* lewa kolumna */\n.pk-lewa {\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  text-align: center;\n  height: 100%;\n}\n.pk-blok {\n  flex: 1;\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  justify-content: center;\n  gap: 36px;\n  padding-top: 24px;\n}\n.pk-ucho { width: 150px; height: auto; display: block; }\n.pk-dane a {\n  display: block;\n  font-family: \"DM Mono\", monospace;\n  font-size: 17px;\n  line-height: 1.9;\n  letter-spacing: .02em;\n  color: #b44430 !important;\n  text-decoration: none !important;\n}\n.pk-dane a:hover { text-decoration: underline !important; }\n\n/* prawa kolumna */\n.pk-sub {\n  font-family: \"DM Mono\", monospace;\n  font-size: 13px;\n  letter-spacing: .14em;\n  text-transform: uppercase;\n  color: rgba(25, 25, 25, .6);\n  margin: 0 0 28px !important;\n}\n.pk-mapa-img {\n  display: block;\n  width: 100% !important;\n  height: auto !important;\n  max-width: none !important;\n  border: 0; border-radius: 0; box-shadow: none;\n}\n\n/* tablet i telefon: jedna kolumna */\n@media (max-width: 921px) {\n  .site-above-footer-wrap[data-section=\"section-above-footer-builder\"] {\n    padding: 56px 0 !important;\n  }\n  .site-above-footer-wrap[data-section=\"section-above-footer-builder\"] .ast-builder-grid-row {\n    grid-template-columns: 1fr !important;\n    row-gap: 56px !important;\n    padding-left: 20px !important;\n    padding-right: 20px !important;\n  }\n  .pk-h2 { font-size: 48px !important; }\n  .pk-h2--mapa { font-size: 40px !important; }\n  .pk-mapa { text-align: center; }\n  .pk-blok { gap: 28px; }\n  .pk-ucho { width: 120px; }\n}\n\n/* ===== Zmiana 2: mniejsza bia\u0142a przerwa pod wizualizacj\u0105 dziedzi\u0144ca (\"O inwestycji\") =====\n   Ukrywa blok Odst\u0119p (101 px) pod sekcj\u0105 z wizualizacj\u0105 (obraz wp-image-657).\n   Zostaje sam dolny padding sekcji (~71 px) \u2013 tyle samo co odst\u0119p nad tekstem.\n   Alternatywa bez CSS: w edytorze strony g\u0142\u00f3wnej usun\u0105\u0107 blok \"Odst\u0119p\" 101 px pod t\u0105 sekcj\u0105. */\n.entry-content > .wp-block-columns:has(.wp-image-657) + .wp-block-spacer {\n  display: none !important;\n}\n\n/* ===== Zmiana 4: strona \"O nas\" \u2013 zdj\u0119cia sekcji przechodz\u0105 p\u0142ynnie jedno w drugie =====\n   Usuwa pionowy odst\u0119p (2 \u00d7 ~71 px) mi\u0119dzy kolejnymi sekcjami (zdj\u0119cie prawe / lewe / prawe).\n   Zostaje odst\u0119p nad pierwsz\u0105 i pod ostatni\u0105 sekcj\u0105. Dotyczy tylko strony \"O nas\" (page-id-18). */\nbody.page-id-18 .entry-content > .wp-block-columns.alignfull {\n  padding-top: 0 !important;\n  padding-bottom: 0 !important;\n}\nbody.page-id-18 .entry-content > .wp-block-columns.alignfull:first-child {\n  padding-top: var(--wp--preset--spacing--80) !important;\n}\nbody.page-id-18 .entry-content > .wp-block-columns.alignfull:last-child {\n  padding-bottom: var(--wp--preset--spacing--80) !important;\n}\n\n/* ===== Zmiana 5: ostre kraw\u0119dzie na ca\u0142ej stronie (zamiast zaokr\u0105gle\u0144) =====\n   Wszystkie elementy na wszystkich podstronach: okno lokalu i jego przycisk \u00d7, pola formularzy,\n   przyciski filtr\u00f3w i prze\u0142\u0105cznik na stronach Lokale/Gastro, karty listy lokali, ikona Instagrama itd.\n   Zostaj\u0105 okr\u0105g\u0142e tylko wska\u017aniki \u0142adowania (formularz, filtry), kropki w ikonie filtr\u00f3w i pola wyboru typu \u201eradio\u201d. */\nbody *,\nbody *::before,\nbody *::after {\n  border-radius: 0 !important;\n}\nbody .wpcf7-spinner,\nbody .wpcf7-spinner::before,\nbody .wpc-spinner::after,\nbody [class*=\"wpc-icon-line\"]::after,\nbody input[type=\"radio\"] {\n  border-radius: 50% !important;\n}\n";document.head.appendChild(s);
